// ===== Job-Scout: Parameter (nur hier ändern) =====
const GMAIL_LABEL = 'Job-Alerts';     // Name des Gmail-Labels, das die Alert-Mails bekommen
const GMAIL_DAYS = 2;                 // nur Mails der letzten N Tage
const BA_DAYS = 2;                    // Bundesagentur: veröffentlicht in den letzten N Tagen
const BA_RADIUS_KM = 25;              // um Berlin
const MAX_PER_RUN = 25;               // Obergrenze neuer Stellen pro Lauf (= max. Gemini-Aufrufe)
const BA_RESERVE = 8;                 // v1.5: so viele Plätze davon bleiben für die Bundesagentur reserviert (wenn BA genug Treffer hat)
const MIN_TEXT = 300;
const HOME = { lat: 0, lon: 0 };  // REFERENCE_POINT: Koordinaten deines Bezugspunkts eintragen
const MAX_KM = 7;                     // Büro höchstens ~7 km Luftlinie (= max. 30 Min. ÖPNV/Fahrrad), sonst nur bei 100 % remote                 // kürzerer Anzeigentext -> Vorprüfung statt Scorer

// Suchbegriffe für die Bundesagentur (ein Aufruf pro Begriff)
const BA_KEYWORDS = [
  'Projektassistenz', 'Projektassistent', 'Assistenz Projektmanagement', 'Projektkoordination', 'Project Coordinator',
  'Projektorganisation', 'PMO', 'Projektmanagement Office',
  'Projektcontrolling', 'Projektsteuerung', 'Junior Controller', 'Kaufmännische Projektsteuerung', 'Projektkaufmann',
  'Kostencontrolling', 'Projektabrechnung', 'Reporting',
  'Operations Specialist', 'Business Operations', 'Prozessmanagement', 'Prozessmanager', 'Prozessoptimierung',
  'Business Process Management', 'Business Analyst', 'Prozessautomatisierung', 'Workflow Automatisierung', 'Automatisierung n8n',
  'KI Automatisierung', 'Low-Code', 'BPMN', 'Digitalisierung Geschäftsprozesse',
];

// Titel-Vorfilter: mindestens ein Treffer (Kleinschreibung, Teilstring) nötig
const TITLE_MUST = ['projekt', 'project', 'pmo', 'koordinat', 'coordinat', 'controll', 'operations', 'prozess', 'process',
  'automat', 'business analy', 'reporting', 'abrechnung', 'kaufmänn', 'kaufmaenn', 'digitalisierung', 'bpmn', 'low-code', 'low code',
  'workflow', 'unit-assisten', 'team-assisten', 'teamassisten', 'assistenz projekt'];
// Titel-Vorfilter: kein Treffer erlaubt
const TITLE_NOT = ['empfang', 'rezeption', 'kasse', 'kassier', 'fraud', 'kyc', 'payroll', 'lohn', 'gehaltsabrechnung', 'store',
  'filiale', 'sekretariat', 'sekretär', 'büromanagement', 'assistenz der geschäftsführung', 'geschäftsführungsassisten',
  'head of', 'leiter', 'leitung', 'director', 'teamlead', 'team lead', 'senior', 'praktik', 'werkstudent', 'ausbildung',
  'azubi', 'trainee', 'pflege', 'arzt', 'ärzt', 'ingenieur', 'engineer (m', 'software engineer', 'developer', 'entwickler'];

// Ort wird im Scout NICHT gefiltert (Entscheidung 2026-11-08). Der Scorer entscheidet anhand des Anzeigentexts.

return [{ json: {
  gmail_label: GMAIL_LABEL, gmail_days: GMAIL_DAYS, ba_days: BA_DAYS, ba_radius: BA_RADIUS_KM,
  max_per_run: MAX_PER_RUN, ba_reserve: BA_RESERVE, min_text: MIN_TEXT,
  ba_keywords: BA_KEYWORDS, title_must: TITLE_MUST, title_not: TITLE_NOT, home: HOME, max_km: MAX_KM,
} }];

// ---- gemeinsame Hilfsfunktionen ----
const P = $('Parameter').first().json;
const lc = s => String(s || '').toLowerCase();
const normKey = s => lc(s).replace(/\(m\/w\/d\)|\(w\/m\/d\)|\(d\/m\/w\)|\(gn\)|\(all genders\)|m\/w\/d|w\/m\/d/g, ' ')
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '');
const canonUrl = u => {
  let s = String(u || '').trim();
  if (!s) return '';
  s = s.replace(/^http:\/\//i, 'https://');
  const m1 = s.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(?:[^\/?#]*-)?(\d+)/i);
  if (m1) return 'https://www.linkedin.com/jobs/view/' + m1[1];
  const m2 = s.match(/[?&]jk=([a-z0-9]+)/i);
  if (m2 && /indeed\./i.test(s)) return 'https://de.indeed.com/viewjob?jk=' + m2[1];
  const m3 = s.match(/stepstone\.de\/[^?#]*?--(\d+)-inline\.html|stepstone\.de\/[^?#]*?-(\d+)(?:-inline)?\.html/i);
  if (m3) return 'https://www.stepstone.de/stellenangebote----' + (m3[1] || m3[2]) + '-inline.html';
  const m4 = s.match(/xing\.com\/jobs\/[^?#]+/i);
  if (m4) return 'https://www.' + m4[0].replace(/^www\./, '');
  return s.split('#')[0].replace(/([?&])(utm_[^&]*|trk=[^&]*|refId=[^&]*|trackingId=[^&]*|tid=[^&]*|from=[^&]*)/g, '$1').replace(/[?&]+$/, '').replace(/\?&/, '?');
};
const titleOk = t => { const s = lc(t); return P.title_must.some(k => s.includes(k)) && !P.title_not.some(k => s.includes(k)); };
const htmlToText = h => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d|section|article)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü').replace(/&szlig;/gi, 'ß').replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// Bekannte Stellen aus Airtable -> Schlüssel (URL und Titel+Arbeitgeber), damit nichts doppelt bewertet wird.
const urls = new Set(), keys = new Set();
for (const it of $input.all()) {
  const f = (it.json && it.json.fields) || it.json || {};
  if (f['Link zur Stelle']) urls.add(canonUrl(f['Link zur Stelle']));
  if (f['Stellentitel']) keys.add(normKey(f['Stellentitel']));
}
return [{ json: { known_urls: [...urls], known_keys: [...keys], known_count: urls.size } }];

const P = $('Parameter').first().json;
const base = 'https://rest.arbeitsagentur.de/jobboerse/jobsuche-service/pc/v6/jobs';
const out = [];
for (const k of P.ba_keywords) {
  out.push({ json: { keyword: k, scope: 'Berlin', url: `${base}?was=${encodeURIComponent(k)}&wo=Berlin&umkreis=${P.ba_radius}&angebotsart=1&veroeffentlichtseit=${P.ba_days}&size=50&page=1` } });
  // Homeoffice-Abfrage (arbeitszeit=ho) liefert in v6 keine Treffer mehr (08.11.2026) -> entfernt
}
return out;

// ---- gemeinsame Hilfsfunktionen ----
const P = $('Parameter').first().json;
const lc = s => String(s || '').toLowerCase();
const normKey = s => lc(s).replace(/\(m\/w\/d\)|\(w\/m\/d\)|\(d\/m\/w\)|\(gn\)|\(all genders\)|m\/w\/d|w\/m\/d/g, ' ')
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '');
const canonUrl = u => {
  let s = String(u || '').trim();
  if (!s) return '';
  s = s.replace(/^http:\/\//i, 'https://');
  const m1 = s.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(?:[^\/?#]*-)?(\d+)/i);
  if (m1) return 'https://www.linkedin.com/jobs/view/' + m1[1];
  const m2 = s.match(/[?&]jk=([a-z0-9]+)/i);
  if (m2 && /indeed\./i.test(s)) return 'https://de.indeed.com/viewjob?jk=' + m2[1];
  const m3 = s.match(/stepstone\.de\/[^?#]*?--(\d+)-inline\.html|stepstone\.de\/[^?#]*?-(\d+)(?:-inline)?\.html/i);
  if (m3) return 'https://www.stepstone.de/stellenangebote----' + (m3[1] || m3[2]) + '-inline.html';
  const m4 = s.match(/xing\.com\/jobs\/[^?#]+/i);
  if (m4) return 'https://www.' + m4[0].replace(/^www\./, '');
  return s.split('#')[0].replace(/([?&])(utm_[^&]*|trk=[^&]*|refId=[^&]*|trackingId=[^&]*|tid=[^&]*|from=[^&]*)/g, '$1').replace(/[?&]+$/, '').replace(/\?&/, '?');
};
const titleOk = t => { const s = lc(t); return P.title_must.some(k => s.includes(k)) && !P.title_not.some(k => s.includes(k)); };
const htmlToText = h => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d|section|article)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü').replace(/&szlig;/gi, 'ß').replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// v6-Antwort: data.ergebnisliste (v4: data.stellenangebote). Feldnamen beider Versionen werden gelesen.
const known = $('Quellen vorbereiten').first().json;
const knownUrls = new Set(known.known_urls), knownKeys = new Set(known.known_keys);
const queries = $('BA: Abfragen bauen').all();
const rad = x => x * Math.PI / 180;
const km = (a, b) => { const dLat = rad(b.lat - a.lat), dLon = rad(b.lon - a.lon); const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2; return 6371 * 2 * Math.asin(Math.sqrt(h)); };
const seen = new Set(); const out = []; let total = 0, errors = 0, tooFar = 0;
const inputs = $input.all();
for (let qi = 0; qi < inputs.length; qi++) {
  const it = inputs[qi]; const kw = (queries[qi] && queries[qi].json.keyword) || '';
  const j = it.json || {};
  if (j.error || (j.statusCode && j.statusCode !== 200)) { errors++; continue; }
  let data = j;
  if (typeof j.data === 'string') { try { data = JSON.parse(j.data); } catch (e) { errors++; continue; } }
  else if (j.data && typeof j.data === 'object') data = j.data;
  const list = (data && (data.ergebnisliste || data.stellenangebote)) || [];
  total += list.length;
  for (const s of list) {
    const ref = s.referenznummer || s.refnr; if (!ref || seen.has(ref)) continue; seen.add(ref);
    const title = s.stellenangebotsTitel || s.titel || s.hauptberuf || '';
    const employer = s.firma || s.arbeitgeber || '';
    const loc = (s.stellenlokationen && s.stellenlokationen[0] && s.stellenlokationen[0].adresse) || s.arbeitsort || {};
    const ort = loc.ort || loc.region || '';
    if (!titleOk(title)) continue;
    // Arbeitsweg: Entfernung Büro <-> REFERENCE_POINT (Luftlinie)
    const lok = s.stellenlokationen && s.stellenlokationen[0];
    let dist = null;
    if (lok && lok.breite && lok.laenge) dist = Math.round(km(P.home, { lat: +lok.breite, lon: +lok.laenge }) * 10) / 10;
    if (dist !== null && dist > P.max_km && !s.homeofficemoeglich) { tooFar++; continue; }
    const url = 'https://www.arbeitsagentur.de/jobsuche/jobdetail/' + encodeURIComponent(ref);
    if (knownUrls.has(canonUrl(url)) || knownKeys.has(normKey(title + ' ' + employer))) continue;
    const facts = [
      'Beruf laut BA: ' + [s.hauptberuf].concat(s.alleBerufe || []).filter((x, i, a) => x && a.indexOf(x) === i).join(', '),
      ort ? 'Arbeitsort: ' + [loc.plz, ort].filter(Boolean).join(' ') : null,
      s.homeofficemoeglich !== undefined ? 'Homeoffice möglich: ' + (s.homeofficemoeglich ? 'ja' : 'nein') + (s.homeofficetyp ? ' (' + s.homeofficetyp + ')' : '') : null,
      (s.gehaltsspanneVon || s.gehaltsspanneBis) ? 'Gehalt: ' + [s.gehaltsspanneVon, s.gehaltsspanneBis].filter(Boolean).join(' bis ') + (s.artDerVerguetung ? ' (' + s.artDerVerguetung + ')' : '') : null,
      dist !== null ? 'Entfernung Büro – REFERENCE_POINT: ' + String(dist).replace('.', ',') + ' km Luftlinie' + (dist > P.max_km ? ' (zu weit für Präsenz; passt nur bei 100 % remote)' : ' (im Radius)') : null,
      s.vertragsdauer ? 'Vertrag: ' + s.vertragsdauer : null,
      s.eintrittszeitraum && s.eintrittszeitraum.von ? 'Eintritt ab: ' + s.eintrittszeitraum.von : null,
    ].filter(Boolean).join('\n');
    out.push({ json: { ext_id: ref, kw, title, employer, place: ort, url, source: 'Bundesagentur für Arbeit', facts,
      detail_url: url,   // öffentliche Detailseite (serverseitig gerendert); die REST-Detail-Endpunkte v3/v4 liefern 403 (Stand 08.11.2026)
      external_url: s.externeURL || s.externeUrl || null } });
  }
}
if (!out.length) return [{ json: { nothing: true, _ba: { total, errors, kept: 0, too_far: tooFar } } }];
// Reihum je Suchbegriff (sonst kommen nur Treffer des ersten Begriffs durch), dann begrenzen
const groups = {}; for (const o of out) (groups[o.json.kw] = groups[o.json.kw] || []).push(o);
// Kreis-Start täglich verschieben: an jedem Tag steht ein anderer Suchbegriff vorn,
// innerhalb von 30 Tagen war jeder Begriff einmal Erster (gleiche Rechnung in "Neue Stellen filtern").
const dayNo = Math.floor(Date.now() / 86400000);
const kwAll = P.ba_keywords;
const shift = kwAll.length ? dayNo % kwAll.length : 0;
const kwOrder = kwAll.slice(shift).concat(kwAll.slice(0, shift));
const keys = kwOrder.filter(k => groups[k]).concat(Object.keys(groups).filter(k => !kwOrder.includes(k)));
const rr = []; let more = true;
for (let i = 0; more; i++) { more = false; for (const k of keys) if (groups[k][i]) { rr.push(groups[k][i]); more = true; } }
const limited = rr.slice(0, P.max_per_run);   // v1.4: nur so viele Detailseiten laden, wie in das Tageslimit passen
limited[0].json._ba = { total, errors, kept: out.length, too_far: tooFar, details_loaded: limited.length, start_kw: kwOrder[0] || null };
return limited;

// ---- gemeinsame Hilfsfunktionen ----
