  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d|section|article)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü').replace(/&szlig;/gi, 'ß').replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// Job-Links aus Alert-Mails. LinkedIn: direkte /jobs/view/<id>-Links. StepStone/Indeed: Tracking-Redirects
// (click.stepstone.de ...), die beim Laden der Seite automatisch auf die Anzeige weiterleiten.
const known = $('Quellen vorbereiten').first().json;
const knownUrls = new Set(known.known_urls), knownKeys = new Set(known.known_keys);
const HOSTS = [
  { re: /linkedin\.com\/(?:comm\/)?jobs\/view\/\d+/i, source: 'LinkedIn / XING' },
  { re: /xing\.com\/(?:m\/)?jobs\//i, source: 'LinkedIn / XING' },
  { re: /stepstone\.(?:de|com)\/(?:stellenangebote|jobs)/i, source: 'Indeed / StepStone' },
  { re: /click\.stepstone\.de\//i, source: 'Indeed / StepStone', redirect: true },
  { re: /indeed\.[a-z.]+\/(?:viewjob|rc\/clk|pagead|jobs)/i, source: 'Indeed / StepStone' },
  { re: /(?:cts|engage|click)\.indeed\.[a-z.]+\//i, source: 'Indeed / StepStone', redirect: true },
];
// Linktexte, die keine Stellentitel sind
const NOT_TITLE = /^(ich\s*bin\s*interessiert|jetzt bewerben|bewerben|ansehen|job ansehen|view|see all jobs|alle jobs|mehr|hier|lebenslauf|diesen job melden|e-mail-einstellungen|diese e-mail|abbestellen|abmelden|unsubscribe|nutzungsbedingungen|datenschutz|kontakt|impressum|hilfe|help|manage|try premium|install|learn why|your job alert|weil du|job-alarm|jobagent)/i;
const seen = new Set(); const out = []; let mails = 0, found = 0, titleDrop = 0;
for (const it of $input.all()) {
  const j = it.json || {}; if (!j.id && !j.html && !j.text) continue; mails++;
  const html = String(j.html || j.textHtml || j.textAsHtml || j.text || '');
  const re = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(html))) {
    const href = m[1].replace(/&amp;/g, '&');
    const h = HOSTS.find(x => x.re.test(href)); if (!h) continue;
    const label = htmlToText(m[2]).replace(/\s+/g, ' ').trim();
    if (!label || label.length < 6 || NOT_TITLE.test(label)) continue;
    const url = h.redirect ? href : canonUrl(href);
    const key = h.redirect ? normKey(label) : url;
    if (!url || seen.has(key) || knownUrls.has(url)) continue;
    // Arbeitgeber und Ort stehen direkt nach dem Link (LinkedIn: "Firma · Ort (Modus)", StepStone: "Firma|Ort|Größe")
    const after = html.slice(re.lastIndex, re.lastIndex + 1500).replace(/<[^>]+>/g, '|')
      .replace(/&nbsp;|&#160;/gi, ' ').replace(/&middot;|&#183;/gi, '·').replace(/&amp;/g, '&').replace(/[\u00a0\u034f\u2060\u200b-\u200d]/g, ' ');
    const parts = after.split('|').map(x => x.replace(/\s+/g, ' ').trim()).filter(x => x && x.length > 1).slice(0, 3);
    let employer = '', place = '';
    if (parts[0] && parts[0].includes('·')) { const p = parts[0].split('·'); employer = p[0].trim(); place = (p[1] || '').trim(); }
    else { employer = parts[0] || ''; place = parts[1] || ''; }
    if (NOT_TITLE.test(employer) || employer.length > 80) employer = '';
    if (knownKeys.has(normKey(label + ' ' + employer))) continue;
    seen.add(key); found++;
    if (!titleOk(label)) { titleDrop++; continue; }   // v1.4: Titel-Vorfilter schon hier, damit nur passende Seiten geladen werden
    out.push({ json: { title: label.replace(/\s*…$|\.\.\.$/, '').slice(0, 160), employer, place, url, source: h.source, mail_subject: j.subject || '' } });
  }
}
if (!out.length) return [{ json: { nothing: true, _gmail: { mails, links: 0, found, title_dropped: titleDrop } } }];
// v1.4: nur so viele Seiten laden, wie in das Tageslimit passen (reihum je Quelle)
const bySrc = {}; for (const o of out) (bySrc[o.json.source] = bySrc[o.json.source] || []).push(o);
const lim = []; let more = true;
for (let i = 0; more && lim.length < P.max_per_run; i++) { more = false; for (const k of Object.keys(bySrc)) if (bySrc[k][i] && lim.length < P.max_per_run) { lim.push(bySrc[k][i]); more = true; } }
lim[0].json._gmail = { mails, links: lim.length, found, title_dropped: titleDrop, over_limit: out.length - lim.length };
return lim;

// ---- gemeinsame Hilfsfunktionen ----
const P = $('Parameter').first().json;
const lc = s => String(s || '').toLowerCase();
const normKey = s => lc(s).replace(/\(m\/w\/d\)|\(w\/m\/d\)|\(d\/m\/w\)|\(gn\)|\(all genders\)|m\/w\/d|w\/m\/d/g, ' ')
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '');
const canonUrl = u => {
  let s = String(u || '').trim();
  if (!s) return '';
  s = s.replace(/^http:\/\//i, 'https://');
  const m1 = s.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(?:[^\/?#]*-)?(\d+)/i);
  if (m1) return 'https://www.linkedin.com/jobs/view/' + m1[1];
  const m2 = s.match(/[?&]jk=([a-z0-9]+)/i);
  if (m2 && /indeed\./i.test(s)) return 'https://de.indeed.com/viewjob?jk=' + m2[1];
  const m3 = s.match(/stepstone\.de\/[^?#]*?--(\d+)-inline\.html|stepstone\.de\/[^?#]*?-(\d+)(?:-inline)?\.html/i);
  if (m3) return 'https://www.stepstone.de/stellenangebote----' + (m3[1] || m3[2]) + '-inline.html';
  const m4 = s.match(/xing\.com\/jobs\/[^?#]+/i);
  if (m4) return 'https://www.' + m4[0].replace(/^www\./, '');
  return s.split('#')[0].replace(/([?&])(utm_[^&]*|trk=[^&]*|refId=[^&]*|trackingId=[^&]*|tid=[^&]*|from=[^&]*)/g, '$1').replace(/[?&]+$/, '').replace(/\?&/, '?');
};
const titleOk = t => { const s = lc(t); return P.title_must.some(k => s.includes(k)) && !P.title_not.some(k => s.includes(k)); };
const htmlToText = h => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d|section|article)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü').replace(/&szlig;/gi, 'ß').replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

const links = $('StepStone: saubere Adresse').all();
if (links.length === 1 && links[0].json.nothing) return [{ json: { nothing: true, _gmail: links[0].json._gmail } }];
const pages = $input.all(); const out = [];
// v1.4: Seiten ohne Anzeige (Login, Cookie-Wand, Sperre, Anzeige offline) liefern KEINEN Text -> Vorprüfung statt Scorer
const BLOCKED = /sign in|anmelden, um fortzufahren|join linkedin|authwall|zugriff verweigert|access denied|captcha|just a moment|we need more cookies|wir brauchen (mehr )?cookies|cookies aktivieren|enable cookies|nicht mehr verfügbar|no longer available|anzeige ist abgelaufen/i;
for (let i = 0; i < links.length; i++) {
  const l = links[i].json; const p = (pages[i] && pages[i].json) || {};
  const status = p.statusCode || 0;
  const html = typeof p.data === 'string' ? p.data : (typeof p.body === 'string' ? p.body : '');
  let title = l.title, employer = l.employer, text = '', place = l.place || '', finalUrl = l.url;
  const og = (typeof p.data === 'string' ? p.data : '').match(/property=["']og:url["'][^>]*content=["']([^"']+)["']/i);
  if (og) finalUrl = og[1];
  if (status === 200 && html) {
    const ld = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || [];
    for (const s of ld) {
      try {
        const o = JSON.parse(s.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
        const arr = Array.isArray(o) ? o : [o];
        const jp = arr.find(x => x && (x['@type'] === 'JobPosting' || (Array.isArray(x['@type']) && x['@type'].includes('JobPosting'))));
        if (jp) {
          title = jp.title || title;
          if (jp.url && /^https?:/.test(jp.url)) finalUrl = jp.url;
          employer = (jp.hiringOrganization && jp.hiringOrganization.name) || employer;
          const loc = jp.jobLocation && (Array.isArray(jp.jobLocation) ? jp.jobLocation[0] : jp.jobLocation);
          place = (loc && loc.address && (loc.address.addressLocality || loc.address.addressRegion)) || '';
          text = htmlToText(jp.description || '');
          break;
        }
      } catch (e) {}
    }
    if (!text) {
      const og = html.match(/property=["']og:title["'][^>]*content=["']([^"']+)["']/i) || html.match(/<title[^>]*>([^<]+)<\/title>/i);
      if (og && (!title || title.length < 10)) title = htmlToText(og[1]).slice(0, 160);
      const body = html.match(/<main[\s\S]*?<\/main>/i) || html.match(/<article[\s\S]*?<\/article>/i) || html.match(/<body[\s\S]*?<\/body>/i);
      text = htmlToText(body ? body[0] : html);
      if (BLOCKED.test(text.slice(0, 2000))) text = '';
    }
  }
  if (!titleOk(title)) continue;
  if (/click\.stepstone\.de\//i.test(finalUrl)) continue;   // Mail-Link nie speichern
  out.push({ json: { title, employer, place, url: finalUrl, source: l.source, text, fetch_status: status, ext_id: finalUrl } });
}
if (!out.length) return [{ json: { nothing: true, _gmail: links[0].json._gmail } }];
out[0].json._gmail = links[0].json._gmail;
return out;

// Karriereseiten der Wunschliste -> API-URLs bekannter ATS (ohne KI). Unbekannte Systeme werden nur gezählt.
const out = []; let withLink = 0; const manual = [];
const host = u => { const m = String(u || '').match(/^https?:\/\/([^\/?#]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
for (const it of $input.all()) {
  const f = (it.json && it.json.fields) || it.json || {};
  const name = f['Name des Arbeitgebers'] || ''; const url = f['Link zur Karriereseite'] || '';
  if (!url) continue; withLink++;
  const h = host(url); const path = String(url).replace(/^https?:\/\/[^\/]+/, '');
  let api = null, ats = null;
  let m;
  if ((m = h.match(/^([a-z0-9-]+)\.jobs\.personio\.(?:de|com)$/))) { ats = 'personio'; api = `https://${m[1]}.jobs.personio.de/xml`; }
  else if (/personio/.test(h)) { ats = 'personio'; api = `https://${h}/xml`; }
  else if ((m = String(url).match(/greenhouse\.io\/([a-z0-9_-]+)/i)) && !/api/.test(h)) { ats = 'greenhouse'; api = `https://boards-api.greenhouse.io/v1/boards/${m[1]}/jobs?content=true`; }
  else if ((m = String(url).match(/lever\.co\/([a-z0-9_-]+)/i))) { ats = 'lever'; api = `https://api.lever.co/v0/postings/${m[1]}?mode=json`; }
  else if ((m = h.match(/^([a-z0-9-]+)\.recruitee\.com$/))) { ats = 'recruitee'; api = `https://${m[1]}.recruitee.com/api/offers/`; }
  else if ((m = String(url).match(/ashbyhq\.com\/([a-z0-9_-]+)/i))) { ats = 'ashby'; api = `https://api.ashbyhq.com/posting-api/job-board/${m[1]}?includeCompensation=false`; }
  else if ((m = String(url).match(/smartrecruiters\.com\/([A-Za-z0-9_-]+)/))) { ats = 'smartrecruiters'; api = `https://api.smartrecruiters.com/v1/companies/${m[1]}/postings?limit=100`; }
  else if ((m = String(url).match(/apply\.workable\.com\/([a-z0-9_-]+)/i))) { ats = 'workable'; api = `https://apply.workable.com/api/v1/widget/accounts/${m[1]}`; }
  if (api) out.push({ json: { employer: name, careers_url: url, ats, api_url: api } });
  else manual.push(name);
}
if (!out.length) return [{ json: { nothing: true, _wl: { withLink, ats: 0, manual } } }];
out[0].json._wl = { withLink, ats: out.length, manual };
return out;

