const src = $('Karriereseiten: API-URLs').all();
if (src.length === 1 && src[0].json.nothing) return [{ json: { nothing: true, _wl: src[0].json._wl } }];
const known = $('Quellen vorbereiten').first().json;
const knownUrls = new Set(known.known_urls), knownKeys = new Set(known.known_keys);
const res = $input.all(); const out = []; const failed = [];
const parse = s => { try { return JSON.parse(s); } catch (e) { return null; } };
const xmlTag = (block, tag) => { const m = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i')); return m ? m[1].replace(/^\s*<!\[CDATA\[|\]\]>\s*$/g, '').trim() : ''; };
for (let i = 0; i < src.length; i++) {
  const s = src[i].json; const r = (res[i] && res[i].json) || {};
  const status = r.statusCode || 0; const body = typeof r.data === 'string' ? r.data : (typeof r.body === 'string' ? r.body : '');
  if (status !== 200 || !body) { failed.push(`${s.employer} (${s.ats}: ${status || 'keine Antwort'})`); continue; }
  const jobs = [];
  if (s.ats === 'personio') {
    for (const blk of body.match(/<position>[\s\S]*?<\/position>/gi) || []) {
      const id = xmlTag(blk, 'id');
      jobs.push({ title: xmlTag(blk, 'name'), place: xmlTag(blk, 'office'), url: s.careers_url.replace(/\/?$/, '') + '/job/' + id,
        text: htmlToText((blk.match(/<jobDescription>[\s\S]*?<\/jobDescription>/gi) || []).map(x => xmlTag(x, 'name') + '\n' + xmlTag(x, 'value')).join('\n\n')) });
    }
  } else if (s.ats === 'greenhouse') {
