  } else if (s.ats === 'lever') {
    for (const j of parse(body) || []) jobs.push({ title: j.text, place: (j.categories && j.categories.location) || '', url: j.hostedUrl, text: j.descriptionPlain || htmlToText(j.description || '') });
  } else if (s.ats === 'recruitee') {
    for (const j of (parse(body) || {}).offers || []) jobs.push({ title: j.title, place: [j.city, j.country].filter(Boolean).join(', ') + (j.remote ? ' Remote' : ''), url: j.careers_url, text: htmlToText((j.description || '') + '\n' + (j.requirements || '')) });
  } else if (s.ats === 'ashby') {
    for (const j of (parse(body) || {}).jobs || []) jobs.push({ title: j.title, place: (j.location || '') + (j.isRemote ? ' Remote' : ''), url: j.jobUrl, text: j.descriptionPlain || htmlToText(j.descriptionHtml || '') });
  } else if (s.ats === 'smartrecruiters') {
    for (const j of (parse(body) || {}).content || []) jobs.push({ title: j.name, place: (j.location && j.location.city) || '', url: `https://jobs.smartrecruiters.com/${j.company && j.company.identifier || ''}/${j.id}`, text: '' });
  } else if (s.ats === 'workable') {
    for (const j of (parse(body) || {}).jobs || []) jobs.push({ title: j.title, place: [j.city, j.country].filter(Boolean).join(', ') + (j.remote ? ' Remote' : ''), url: j.url, text: htmlToText(j.description || '') });
  }
  for (const j of jobs) {
    if (!j.title || !j.url) continue;
    if (!titleOk(j.title)) continue;   // Ort entscheidet der Scorer
    const cu = canonUrl(j.url);
    if (knownUrls.has(cu) || knownKeys.has(normKey(j.title + ' ' + s.employer))) continue;
    out.push({ json: { title: j.title, employer: s.employer, place: j.place, url: j.url, source: 'Karriereseite Wunschliste', text: j.text || '', ext_id: cu } });
  }
}
