}
// Reihenfolge: zuerst ALLE Stellen aus Gmail-Alerts und Wunschliste (bereits vorgefiltert, reihum je Quelle),
// danach die BA-Suchbegriffe reihum, deren Start sich täglich verschiebt.
const BA = 'Bundesagentur für Arbeit';
const groups = {}; for (const o of out) { const g = o.json.source + '|' + (o.json._kw || ''); (groups[g] = groups[g] || []).push(o); }
// Kreis-Start täglich verschieben: an jedem Tag steht ein anderer Suchbegriff vorn,
// innerhalb von 30 Tagen war jeder Begriff einmal Erster (gleiche Rechnung in "Neue Stellen filtern").
const dayNo = Math.floor(Date.now() / 86400000);
const kwAll = P.ba_keywords;
const shift = kwAll.length ? dayNo % kwAll.length : 0;
const kwOrder = kwAll.slice(shift).concat(kwAll.slice(0, shift));
const gAll = Object.keys(groups);
const gOther = gAll.filter(g => !g.startsWith(BA + '|'));
const gBa = kwOrder.map(k => BA + '|' + k).filter(g => groups[g]).concat(gAll.filter(g => g.startsWith(BA + '|') && !kwOrder.includes(g.slice(BA.length + 1))));
const roundRobin = keys => { const res = []; let more = true;
  for (let i = 0; more; i++) { more = false; for (const k of keys) if (groups[k][i]) { res.push(groups[k][i]); more = true; } }
  return res; };
// v1.5: Alerts und Wunschliste zuerst, aber BA_RESERVE Plätze bleiben für die Bundesagentur frei (11.11.: Gmail nahm alle 25).
const rrOther = roundRobin(gOther), rrBa = roundRobin(gBa);
const reserveBa = Math.min(P.ba_reserve || 0, rrBa.length);
const takeOther = rrOther.slice(0, Math.max(0, P.max_per_run - reserveBa));
const takeBa = rrBa.slice(0, P.max_per_run - takeOther.length);
let capped = takeOther.concat(takeBa);
if (capped.length < P.max_per_run) capped = capped.concat(rrOther.slice(takeOther.length, takeOther.length + P.max_per_run - capped.length));
const summary = { ...meta, candidates: out.length, dropped_duplicates: dropped, processed: capped.length, skipped_over_cap: out.length - capped.length, ba_start_kw: kwOrder[0] || null, from_ba: capped.filter(o => o.json.source === BA).length };
if (!capped.length) return [{ json: { nothing: true, _summary: summary } }];
capped[0].json._summary = summary;
return capped;

// Kein ausreichender Anzeigentext: Datensatz ohne Bewertung anlegen.
