// Kurze Telegram-Meldung: nur passende Stellen mit Link, Rest als Zahlen.
const first = $('Neue Stellen filtern').first().json;
const s = first._summary || {};
const allRuns = name => { const res = []; for (let r = 0; r < 500; r++) { let items; try { items = $(name).all(0, r); } catch (e) { break; } if (!items || !items.length) { if (r > 0) break; else continue; } res.push(...items); } return res; };
const short = t => String(t || '?').replace(/\s*\((?:m\/w\/d|w\/m\/d|d\/m\/w|m\/w\/div|f\/m\/d|all genders?)\)/gi, '').replace(/\s+/g, ' ').trim().slice(0, 70);
const AT = 'https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_JOBS_TABLE_ID/';
let top = [], near = 0, low = 0, excl = 0, vor = 0, errs = 0;
try { for (const it of allRuns('Scorer aufrufen')) { const r = it.json || {}; const sc = Number(r['Score']);
  if (r.error) { errs++; continue; }   // v1.5: Scorer-Aufruf selbst fehlgeschlagen
  if (r['Speicherfehler']) errs++;
  if (r['Harter Ausschluss'] && r['Harter Ausschluss'].length) { excl++; continue; }
  if (sc >= 75) top.push({ sc, t: short(r['Stelle']), id: r['Airtable-Datensatz'] }); else if (sc >= 65) near++; else low++; } } catch (e) {}
try { for (const it of allRuns('Vorprüfung speichern')) { const r = it.json || {}; if (r.error) errs++; vor += (r.records || []).length; } } catch (e) {}
top.sort((a, b) => b.sc - a.sc);
const day = $now.toFormat('dd.MM.');
if (!(s.processed > 0)) return [{ json: { text: `🔎 Job-Scout ${day}: keine neuen Stellen.` } }];
const lines = [`🔎 Job-Scout ${day} · ${s.processed} neu bewertet`];
if (top.length) { lines.push('', `✅ Passend (${top.length}):`); top.forEach((x, i) => lines.push(`${i + 1}. ${x.sc} · ${x.t}` + (x.id ? `\n   ${AT}${x.id}` : ''))); }
else lines.push('', 'Heute nichts ab 75.');
const rest = [near ? `${near} knapp darunter (65–74)` : null, low ? `${low} passen nicht` : null, excl ? `${excl} ausgeschlossen` : null, vor ? `${vor} ohne Text (Vorprüfung)` : null].filter(Boolean);
if (rest.length) lines.push('', rest.join(' · '));
if (s.skipped_over_cap) lines.push(`${s.skipped_over_cap} über dem Tageslimit, nicht bewertet.`);
if (s.gmail && s.gmail.stepstone_unresolved) lines.push(`${s.gmail.stepstone_unresolved} StepStone-Links nicht auflösbar (in der Alert-Mail öffnen).`);
if (errs) lines.push(`⚠️ ${errs} Fehler beim Bewerten oder Speichern – in n8n prüfen.`);
return [{ json: { text: lines.join('\n'), summary: s } }];

// ---- gemeinsame Hilfsfunktionen ----
const P = $('Parameter').first().json;
const lc = s => String(s || '').toLowerCase();
const normKey = s => lc(s).replace(/\(m\/w\/d\)|\(w\/m\/d\)|\(d\/m\/w\)|\(gn\)|\(all genders\)|m\/w\/d|w\/m\/d/g, ' ')
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '');
const canonUrl = u => {
  let s = String(u || '').trim();
  if (!s) return '';
  s = s.replace(/^http:\/\//i, 'https://');
  const m1 = s.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(?:[^\/?#]*-)?(\d+)/i);
  if (m1) return 'https://www.linkedin.com/jobs/view/' + m1[1];
  const m2 = s.match(/[?&]jk=([a-z0-9]+)/i);
  if (m2 && /indeed\./i.test(s)) return 'https://de.indeed.com/viewjob?jk=' + m2[1];
  const m3 = s.match(/stepstone\.de\/[^?#]*?--(\d+)-inline\.html|stepstone\.de\/[^?#]*?-(\d+)(?:-inline)?\.html/i);
  if (m3) return 'https://www.stepstone.de/stellenangebote----' + (m3[1] || m3[2]) + '-inline.html';
  const m4 = s.match(/xing\.com\/jobs\/[^?#]+/i);
  if (m4) return 'https://www.' + m4[0].replace(/^www\./, '');
  return s.split('#')[0].replace(/([?&])(utm_[^&]*|trk=[^&]*|refId=[^&]*|trackingId=[^&]*|tid=[^&]*|from=[^&]*)/g, '$1').replace(/[?&]+$/, '').replace(/\?&/, '?');
};
const titleOk = t => { const s = lc(t); return P.title_must.some(k => s.includes(k)) && !P.title_not.some(k => s.includes(k)); };
const htmlToText = h => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d|section|article)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü').replace(/&szlig;/gi, 'ß').replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// v1.4: StepStone-Mail-Links (click.stepstone.de) sind Anmelde-Links und enden auf einer Cookie-Seite.
// Der Knoten davor ruft sie OHNE Weiterleitung auf; in der Antwort (302) steht die Stellennummer.
// Hier wird daraus die saubere Adresse gebaut. Der Mail-Link selbst wird nie weitergegeben oder gespeichert.
const links = $('Gmail: Links extrahieren').all();
if (links.length === 1 && links[0].json.nothing) return [{ json: links[0].json }];
const known = $('Quellen vorbereiten').first().json;
const knownUrls = new Set(known.known_urls);
const res = $input.all();
const aligned = res.length === links.length;
const isClick = u => /click\.stepstone\.de\//i.test(String(u || ''));
