  if (isClick(l.url)) {
    const r = aligned ? ((res[i] && res[i].json) || {}) : {};
    const hd = r.headers || {};
    let hay = [hd.location, hd.Location, typeof r.data === 'string' ? r.data : '', typeof r.body === 'string' ? r.body : ''].filter(Boolean).join(' ');
    try { hay += ' ' + decodeURIComponent(hay); } catch (e) {}
    const m = hay.match(/-{2,}(\d{6,})-inline\.html/i);
    if (!m) { meta.stepstone_unresolved++; continue; }
    l.url = 'https://www.stepstone.de/stellenangebote----' + m[1] + '-inline.html';
    meta.stepstone_resolved++;
